create or replace TABLE LDL_PRODUCTION_CLONE_GOOGLE_20260608_1030.P_LEW_MART_LIDL_DIGITAL.T_AGG_CUST_REG_DEREG_LDPL_WK (
	CLIENT_ID NUMBER(38,0) NOT NULL COMMENT 'Client Identifier',
	CY_WEEK NUMBER(38,0) NOT NULL COMMENT 'Week identifier',
	HARMO_CAL_WEEK_NO NUMBER(38,0) NOT NULL COMMENT 'Harmonized week no per country - week since rollout',
	GENDER_CD VARCHAR(5) NOT NULL COMMENT 'The code for the gender',
	AGE_RANGE_CD VARCHAR(10) NOT NULL COMMENT 'The code for the age range.',
	HOUSEHOLD_TYPE_ID NUMBER(38,0) NOT NULL COMMENT 'ID of the household type in which the customer lives.',
	CHILD_AGE_RANGE_GROUP_ID NUMBER(38,0) NOT NULL COMMENT 'Group of one or more age ranges in which the child is categorized depending on the age.',
	DISTINCT_REG_USER_FG VARCHAR(1) NOT NULL COMMENT 'Distinct registered user flag. Y - registered users for INT',
	REG_INTERFACE_ID NUMBER(38,0) NOT NULL COMMENT 'Id of the registration interface through which the user registered or reregistered for the geographical area in the loyalty program by accepting the legal terms the first time.',
	WK_RF_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of recency-frequency segments from rfm model',
	WK_M_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'ids of monetary segments from rfm model',
	WK_ST_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'Ids of strategic segments from rfm model - used (MTH_RF_SEGMENT_SID) to select p_lew_core.t_ref_segment.segment_sid',
	WK_RE_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'Ids of recency segments from rfm model - used (MTH_RE_SEGMENT_SID) to select p_lew_core.t_ref_segment.segment_sid',
	WK_FR_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'Ids of frequency segments from rfm model - used (MTH_RF_SEGMENT_SID) to select p_lew_core.t_ref_segment.segment_sid',
	WK_MO_SEGMENT_SID NUMBER(38,0) DEFAULT 0 COMMENT 'Ids of new monetary segments from rfm model - used (MTH_RF_SEGMENT_SID) to select p_lew_core.t_ref_segment.segment_sid',
	CW_REG_CNT NUMBER(38,0) COMMENT 'Number of registrations for given week',
	PW_REG_CNT NUMBER(38,0) COMMENT 'Number of registrations for previous week',
	PYW_REG_CNT NUMBER(38,0) COMMENT 'Number of registrations for previous year week',
	CW_TOTAL_REG_CNT NUMBER(38,0) COMMENT 'Number of total registrations since reporting_start_dt to given week',
	PW_TOTAL_REG_CNT NUMBER(38,0) COMMENT 'Number of total registrations since reporting_start_dt to previous week',
	PYW_TOTAL_REG_CNT NUMBER(38,0) COMMENT 'Number of total registrations since reporting_start_dt to previous year week',
	CW_DEREG_CNT NUMBER(38,0) COMMENT 'Number of deregistrations for given week',
	PW_DEREG_CNT NUMBER(38,0) COMMENT 'Number of deregistrations for previous week',
	PYW_DEREG_CNT NUMBER(38,0) COMMENT 'Number of deregistrations for previous year week',
	CW_TOTAL_DEREG_CNT NUMBER(38,0) COMMENT 'Number of total deregistrations since reporting_start_dt to given week',
	PW_TOTAL_DEREG_CNT NUMBER(38,0) COMMENT 'Number of total deregistrations since reporting_start_dt to previous week',
	PYW_TOTAL_DEREG_CNT NUMBER(38,0) COMMENT 'Number of total deregistrations since reporting_start_dt to previous year week',
	CW_NEW_REG_CNT NUMBER(38,0) COMMENT 'Number of new registrations for given week',
	PW_NEW_REG_CNT NUMBER(38,0) COMMENT 'Number of new registrations for previous week',
	PYW_NEW_REG_CNT NUMBER(38,0) COMMENT 'Number of new registrations for previous year week',
	CW_TOTAL_NEW_REG_CNT NUMBER(38,0) COMMENT 'Number of total new registrations since reporting_start_dt to given week',
	PW_TOTAL_NEW_REG_CNT NUMBER(38,0) COMMENT 'Number of total new registrations since reporting_start_dt to previous week',
	PYW_TOTAL_NEW_REG_CNT NUMBER(38,0) COMMENT 'Number of total new registrations since reporting_start_dt to previous year week',
	LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'Load identifier',
	DWH_CREATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Row created time',
	DWH_UPDATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Row update time',
	constraint PK_CUST_REG_DEREG_LDPL_WK primary key (CLIENT_ID, GENDER_CD, AGE_RANGE_CD, DISTINCT_REG_USER_FG, CY_WEEK)
)COMMENT=' Lidlplus: Table to provide registration and deregistration of customers count at week level'
;